package com.labmaker.app;
import com.getcapacitor.*;import com.getcapacitor.annotation.CapacitorPlugin;import okhttp3.*;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@CapacitorPlugin(name="LabContributions")
public class LabContributionsPlugin extends Plugin {
 private static final class Task {final String id;final FeedbackUpload.Work work=new FeedbackUpload.Work();Task(String id){this.id=id;}}
 private final AtomicReference<Task> active=new AtomicReference<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private final OkHttpClient client=new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false).connectTimeout(15,TimeUnit.SECONDS).readTimeout(60,TimeUnit.SECONDS).writeTimeout(60,TimeUnit.SECONDS).callTimeout(120,TimeUnit.SECONDS).build();
 @PluginMethod public void cancel(PluginCall call){Task task=active.get();if(task!=null&&task.id.equals(call.getString("id","")))task.work.cancel();call.resolve();}
 @PluginMethod public void submit(PluginCall call){Task task=new Task(call.getString("id",""));if(!task.id.matches("[a-f0-9-]{36}")){call.reject("贡献标识无效");return;}if(!active.compareAndSet(null,task)){call.reject("贡献正在提交，请稍候");return;}worker.execute(()->{try{String exp=call.getString("experiment",""),kind=call.getString("kind","");JSONObject catalog;try(java.io.InputStream in=getContext().getAssets().open("public/report-runtime/catalog.json")){catalog=new JSONObject(new String(FeedbackUpload.bounded(in,2*1024*1024),java.nio.charset.StandardCharsets.UTF_8));}boolean known=false;JSONArray experiments=catalog.getJSONArray("experiments");for(int i=0;i<experiments.length();i++)if(exp.equals(experiments.getJSONObject(i).getString("sourceId")))known=true;if(!known)throw new java.io.IOException("未找到对应实验");java.util.List<ContributionUpload.Item> files=ContributionUpload.plan(getContext().getCacheDir(),task.id,exp,kind,call.getArray("files"));ContributionUpload upload=new ContributionUpload(new FeedbackUpload(client,HttpUrl.get(FeedbackUpload.ENDPOINT),HttpUrl.get(FeedbackUpload.DESTINATION)));call.resolve(JSObject.fromJSONObject(upload.submit(task.id,exp,kind,files,task.work)));}catch(Exception e){call.reject(e.getMessage()==null?"贡献未能提交":e.getMessage(),"CONTRIBUTION_SEND");}finally{active.compareAndSet(task,null);}});}
 @Override protected void handleOnDestroy(){Task task=active.get();if(task!=null)task.work.cancel();worker.shutdownNow();}
}
